import React, { useEffect, useState } from 'react';
import Sidebar from '../components/Sidebar';

const PreviewQuestion = ({ question, numbering }) => {
    return (
        <div className="mb-6">

            {/* Question Number + Text */}
            <div className="flex gap-2 mb-3">

                <span className="font-bold text-gray-700">
                    {numbering}.
                </span>

                <p className="text-gray-800 font-medium">
                    {question.text}
                </p>

            </div>

            {/* Preview Answer Field */}
            {/* User Answers Preview */}
            <div className="ml-6 mb-4">

                {question.type === 'Short Answer' ? (

                    <div
                        className="
                border
                rounded-lg
                p-3
                bg-gray-50
                text-gray-700
                min-h-[50px]
            "
                    >
                        {question.userAnswer || (
                            <span className="text-gray-400">
                                No answer provided
                            </span>
                        )}
                    </div>

                ) : (

                    <div className="flex gap-6">

                        <div
                            className={`
                    px-4 py-2 rounded-lg border
                    ${question.userAnswer === 'True'
                                    ? 'bg-green-100 border-green-400 text-green-700'
                                    : 'bg-gray-50'
                                }
                `}
                        >
                            True
                        </div>

                        <div
                            className={`
                    px-4 py-2 rounded-lg border
                    ${question.userAnswer === 'False'
                                    ? 'bg-red-100 border-red-400 text-red-700'
                                    : 'bg-gray-50'
                                }
                `}
                        >
                            False
                        </div>

                    </div>

                )}

            </div>

            {/* Child Questions */}
            {question.children?.length > 0 && (

                <div className="ml-8 border-l-2 border-gray-300 pl-4 mt-4">

                    {question.children.map((child, index) => (

                        <PreviewQuestion
                            key={child.id}
                            question={child}
                            numbering={`${numbering}.${index + 1}`}
                        />

                    ))}

                </div>

            )}

        </div>
    );
};

const PreviewPage = () => {
    const [questions, setQuestions] = useState([]);

    useEffect(() => {
        const saved = localStorage.getItem('questions');

        if (saved) {
            setQuestions(JSON.parse(saved));
        }
    }, []);

    return (
        <div className="flex bg-gradient-to-br from-slate-900 via-slate-800 to-indigo-950 min-h-screen">

            {/* Sidebar */}
            <Sidebar />

            {/* Main Content */}
            <div className="flex-1 p-8 overflow-auto">

                {/* A4 Sheet */}
                <div
                    className="
                        bg-white/95 backdrop-blur-md
                        mx-auto
                        shadow-2xl
                        rounded-md
                        p-12
                    "
                    style={{
                        width: '794px',
                        minHeight: '1123px',
                    }}
                >

                    {/* Header */}
                    <div className="mb-10 text-center border-b pb-6">

                        <h1 className="text-4xl font-bold text-slate-800 mb-2">
                            Form Preview
                        </h1>

                        <p className="text-slate-500">
                            A4 Printable Form Layout
                        </p>

                    </div>

                    {/* Questions */}
                    {questions.length === 0 ? (

                        <div className="text-center text-gray-400 mt-20">
                            No Questions Available
                        </div>

                    ) : (

                        questions.map((question, index) => (

                            <PreviewQuestion
                                key={question.id}
                                question={question}
                                numbering={`Q${index + 1}`}
                            />

                        ))

                    )}

                </div>

            </div>

        </div>
    );
};

export default PreviewPage;
